import React, { useState } from 'react'
import logo_moreinfo from "../ProfitabilityResults/assets/moreInfo.png"

const ProfitabilityResults = () => {
    const [showTooltip, setShowTooltip] = useState(false);

    const invoiceProfitability = {
        charge: "$0.00",
        expectedIncome: "$0.00",
        realIncome: "$0.00",
        hours: "1:00",
        overallProfitability: "0%",
    };

    return (
        <div style={{
            display: 'flex',
            alignItems: 'center',
            padding: '20px',
            background: '#E6E9F0',
            borderRadius: '12px',
            width: '600px',
            position: 'relative'
        }}>

            {/* Lado izquierdo */}
            <div style={{ flex: 1 }}>
                <div>Cobro: {invoiceProfitability.charge}</div>
                <div>Ingreso OB: {invoiceProfitability.expectedIncome}</div>
                <div>Ingreso real: {invoiceProfitability.realIncome}</div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                    <span>Horas: {invoiceProfitability.hours}</span>

                    <img
                        src={logo_moreinfo}
                        alt="info"
                        style={{ width: '14px', cursor: 'pointer' }}
                        onMouseEnter={() => setShowTooltip(true)}
                        onMouseLeave={() => setShowTooltip(false)}
                    />
                </div>
            </div>

            {/* Separador */}
            <div style={{
                width: '1px',
                height: '80px',
                background: '#999',
                margin: '0 20px'
            }} />

            {/* Lado derecho */}
            <div style={{ flex: 1 }}>
                <div style={{ fontSize: '20px', marginBottom: '10px' }}>
                    Rentabilidad: {invoiceProfitability.overallProfitability}
                </div>

                <button style={{
                    padding: '8px 12px',
                    borderRadius: '8px',
                    background: '#4F7DF0',
                    color: 'white',
                    border: 'none',
                    cursor: 'pointer'
                }}>
                    Ver gráfico...
                </button>
            </div>

            {/* Tooltip */}
            {showTooltip && (
                <div style={{
                    position: 'absolute',
                    bottom: '100%',
                    left: '40px',
                    marginBottom: '10px',
                    background: 'white',
                    border: '2px solid #4F7DF0',
                    borderRadius: '10px',
                    padding: '10px',
                    width: '200px'
                }}>
                    <div>Horas proyectadas: 100 horas</div>
                    <div>Horas reales: 100 horas</div>
                </div>
            )}
        </div>
    )
}

export default ProfitabilityResults
